-- Capital Square: no price lists on the site. Model units built from the floor
-- plans replace individual units with prices (those stay soft-deleted).
ALTER TABLE "properties" ADD COLUMN "floor_note" TEXT;

UPDATE "properties" SET "deleted_at" = CURRENT_TIMESTAMP AT TIME ZONE 'UTC'
WHERE "project_id" IN (SELECT "id" FROM "projects" WHERE "slug" = 'capital-square')
  AND "sale_price_vnd" IS NOT NULL AND "deleted_at" IS NULL;

INSERT INTO "properties" (
  "id", "slug", "name", "project_id", "property_type_id", "unit_code", "tower", "floor_note",
  "for_rent", "for_sale", "availability", "status", "published_at", "location",
  "area_m2", "bedrooms", "bathrooms", "furnishing", "cover_image_id", "description", "updated_at")
